<script setup lang="ts">const{api,token}=useShopApi(),unread=useState('notification-unread',()=>0);onMounted(async()=>{if(token.value){const r=await api<any>('/notifications');unread.value=r.unread}})</script>
<template><NuxtLink v-if="token" to="/profile/notifications" class="fixed bottom-5 left-5 z-40 grid size-12 place-items-center rounded-full bg-slate-900 text-xl text-white shadow-xl" title="اعلان‌ها">♢<span v-if="unread" class="absolute -right-1 -top-1 grid size-6 place-items-center rounded-full bg-rose-600 text-[10px] font-bold">{{unread>99?'99+':unread}}</span></NuxtLink></template>
